import {execFileSync} from 'node:child_process';
import {mkdtempSync, mkdirSync, rmSync, writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, resolve} from 'node:path';

// specs/lore-test-descriptors/spec.md#1
it('includes the stamped spec anchor in a test descriptor', () => {
  const root = mkdtempSync(join(tmpdir(), 'lore-list-'));
  try {
    const bin = join(root, 'bin');
    mkdirSync(bin);
    const file = join(root, 'sample.test.ts');
    writeFileSync(file, '// specs/example/spec.md#3\\nit(\"example\", () => {});\\n');
    const report = JSON.stringify({testResults: [{name: file, assertionResults: [{fullName: 'example'}]}]});
    writeFileSync(join(bin, 'npx'), "'`#!/bin/sh'"\\nfor arg in \""'$@"; do'"\\n  case \""'$arg" in --outputFile=*) printf '"'%s' '"'${report}'"' > \""'${'"'"'$'"'}{arg#--outputFile=}\";; esac\\ndone\\n"'`, {mode: 0o755});
    const output = execFileSync('"'node', [resolve('scripts/lore-list-tests.mjs')], {
      cwd: root,
      env: {...process.env, PATH: "'`${bin}:${process.env.PATH ?? '"''}"'`},
      encoding: '"'utf8',
    });
    expect(JSON.parse(output)).toEqual([{id: 'sample.test.ts::example', name: 'example', file: 'sample.test.ts', spec: 'specs/example/spec.md#3'}]);
  } finally {
    rmSync(root, {recursive: true, force: true});
  }
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath scripts/lore-list-tests.test.ts"
